int failures=0,checks=0;
void check(bool b,const char*n,double v=0){++checks;std::cout<<(b?"PASS ":"FAIL ")<<n<<" "<<v<<std::endl;if(!b)++failures;}
double energy(const std::vector<float>& x){double v=0;for(auto a:x)v+=a*a;return v;}
void wav(const char* path,const Render&r){std::ofstream f(path,std::ios::binary);auto u16=[&](uint16_t v){f.write((char*)&v,2);};auto u32=[&](uint32_t v){f.write((char*)&v,4);};uint32_t n=uint32_t(r.left.size())*8;f.write("RIFF",4);u32(n+36);f.write("WAVEfmt ",8);u32(16);u16(3);u16(2);u32(uint32_t(r.rate));u32(uint32_t(r.rate)*8);u16(8);u16(32);f.write("data",4);u32(n);for(size_t i=0;i<r.left.size();++i){f.write((char*)&r.left[i],4);f.write((char*)&r.right[i],4);}}
int main(int argc,char**argv){if(argc>1){std::ifstream file("speech.raw",std::ios::binary|std::ios::ate);auto count=size_t(file.tellg())/4;file.seekg(0);Clip c;c.rate=48000;c.left.resize(count);file.read((char*)c.left.data(),count*4);c.right=c.left;Settings a;a.voices=12;a.dry=0;a.mix=1;a.level=-6;Render r;if(!render(Kind::Crowd,c,a,r))return 1;wav("speech-crowd-after.wav",r);gill::before16::Clip oc;oc.rate=c.rate;oc.left=c.left;oc.right=c.right;gill::before16::Settings os;os.voices=12;os.dry=0;os.mix=1;os.level=-6;gill::before16::Render o;if(!gill::before16::render(gill::before16::Kind::Crowd,oc,os,o))return 1;r.left=o.left;r.right=o.right;wav("speech-crowd-before.wav",r);std::cout<<"SPEECH_RENDER_PASS";return 0;}Clip clip;clip.rate=24000;clip.left.resize(24000);clip.right.resize(24000);for(int i=0;i<24000;++i){double t=i/clip.rate;clip.left[i]=clip.right[i]=float((.19*sin(2*pi*220*t)+.06*sin(2*pi*440*t)+.035*sin(2*pi*880*t))*fade(i,24000,240));}Settings s;s.voices=6;s.dry=0;s.level=0;s.mix=1;Render base;check(render(Kind::Crowd,clip,s,base),"crowd base render");wav("crowd-after.wav",base);Render src;static_cast<Clip&>(src)=clip;wav("source.wav",src);
gill::before16::Clip oldClip;oldClip.rate=clip.rate;oldClip.left=clip.left;oldClip.right=clip.right;gill::before16::Settings oldS;oldS.voices=6;oldS.dry=0;oldS.level=0;oldS.mix=1;gill::before16::Render oldR;gill::before16::render(gill::before16::Kind::Crowd,oldClip,oldS,oldR);Render before;before.rate=oldR.rate;before.left=oldR.left;before.right=oldR.right;wav("crowd-before.wav",before);
Render repeat;render(Kind::Crowd,clip,s,repeat);check(base.left==repeat.left&&base.right==repeat.right,"repeat render deterministic");
s.mix=.25f;Render quarter;render(Kind::Crowd,clip,s,quarter);double ratio=energy(quarter.left)/energy(base.left);check(std::abs(ratio-.0625)<1e-5,"effect control changes wet level",ratio);s.mix=1;s.level=-6;render(Kind::Crowd,clip,s,quarter);ratio=energy(quarter.left)/energy(base.left);check(std::abs(ratio-pow(10.,-.6))<1e-5,"output gain calibrated",ratio);s.level=0;s.width=0;render(Kind::Crowd,clip,s,quarter);check(quarter.left==quarter.right,"width zero exact mono");s.width=1;
s.width=.8f;for(int style=0;style<3;++style){s.style=style;render(Kind::Crowd,clip,s,quarter);check(style?quarter.left!=base.left:quarter.left==base.left,"isolated choir style");}s.style=0;s.width=1;
Clip right=clip;std::fill(right.left.begin(),right.left.end(),0);check(render(Kind::Crowd,right,s,quarter)&&energy(quarter.left)>1,"right-only source sings");check(render(Kind::Stutter,right,s,quarter)&&energy(quarter.right)>1&&energy(quarter.left)>1,"right-only stutter audible both pans");Clip opposed=clip;for(auto&x:opposed.right)x=-x;check(render(Kind::Crowd,opposed,s,quarter)&&energy(quarter.left)>1,"polarity-opposed choir survives");wav("crowd-opposed.wav",quarter);
s.start=.25;s.end=.75;render(Kind::Crowd,clip,s,quarter);check(quarter.left.size()==28800&&quarter.onset==6000,"source trim controls respected");s.start=0;s.end=1;Render fullTone;s.tone=1;render(Kind::Crowd,clip,s,fullTone);s.tone=0;render(Kind::Crowd,clip,s,quarter);check(quarter.left!=fullTone.left,"isolated tone changes render");s.tone=.6f;s.mix=0;s.dry=1;render(Kind::Crowd,clip,s,quarter);double err=0;for(int i=240;i<23760;++i)err=std::max(err,std::abs(double(quarter.left[i]-clip.left[i])));check(err==0,"direct is unfiltered at unity",err);s.mix=1;s.dry=0;
Render controlA,controlB;s.amount=0;render(Kind::Crowd,clip,s,controlA);s.amount=1;render(Kind::Crowd,clip,s,controlB);check(controlA.left!=controlB.left,"isolated HUMAN changes voices");s.amount=.65f;s.time=0;render(Kind::Crowd,clip,s,controlA);s.time=1;render(Kind::Crowd,clip,s,controlB);check(controlA.left!=controlB.left,"isolated TIMING changes voices");s.time=.5f;s.voices=4;render(Kind::Crowd,clip,s,controlA);s.voices=24;render(Kind::Crowd,clip,s,controlB);check(controlA.left!=controlB.left,"isolated PEOPLE changes group");s.voices=6;
Clip silent=clip;std::fill(silent.left.begin(),silent.left.end(),0);silent.right=silent.left;check(!render(Kind::Crowd,silent,s,quarter),"silence rejected");check(!render(Kind::Crowd,clip,s,quarter,[]{return true;}),"cancel honored");
for(int k=0;k<7;++k){check(render(Kind(k),clip,s,quarter),"all mechanisms render");check(quarter.left.front()==0&&quarter.left.back()==0,"render edges zero");bool good=true;double peak=0;for(auto x:quarter.left){good&=std::isfinite(x);peak=std::max(peak,std::abs(double(x)));}check(good&&peak<=.892,"finite headroom",peak);}
for(double fs:{8000.,44100.,48000.,96000.,192000.})for(int k=0;k<7;++k){Engine engine{Kind(k)};engine.prepare(fs);Settings a;a.bypass=true;float l[128]{},r[128]{};l[0]=.5f;r[0]=-.25f;engine.process(l,r,128,a);check(l[0]==.5f&&r[0]==-.25f,"startup native bypass exact");engine.reset();l[0]=.5f;r[0]=-.25f;engine.process(l,r,128,a);check(l[0]==.5f&&r[0]==-.25f,"seek bypass exact");l[0]=std::numeric_limits<float>::quiet_NaN();r[0]=std::numeric_limits<float>::infinity();engine.process(l,r,128,a);check(std::isfinite(l[0])&&std::isfinite(r[0]),"invalid audio finite");}
for(int k:{1,2,3,4}){gill::before16::Engine old{gill::before16::Kind(k)};old.prepare(48000);gill::before16::Settings a;a.bypass=true;float l[128]{},r[128]{};l[0]=.5f;r[0]=-.25f;old.process(l,r,128,a);check(l[0]!=.5f,"old startup bypass negative control fails identity",l[0]);}
std::cout<<"RESULT "<<checks<<" checks "<<failures<<" failures\n";return failures?1:0;}
